#!/usr/bin/env Rscript
args<-commandArgs(TRUE);project<-normalizePath(if(length(args))args[1]else'paper19opp-revision2');p<-file.path(project,'upr_robustness','ranking');options(stringsAsFactors=FALSE);.libPaths(c(file.path(dirname(project),'.Rlib'),.libPaths()))
r<-function(n)read.delim(file.path(p,n),check.names=FALSE)
q<-subset(r('quintile_group_summaries.tsv'),cohort=='all438');genes<-subset(r('source_quintile_membership.tsv'),cohort=='all438');m<-subset(r('fixed_ranking_metrics.tsv'),cohort=='complete370');null<-subset(r('all100_fixed_null_ranking_metrics.tsv'),cohort=='complete370');unif<-subset(r('uniform_random_ranking_reference.tsv'),cohort=='complete370')
blue<-'#4C78A8';ink<-'#303030';grey<-'#B7BEC4';light<-'#DDE1E5';ks<-c(10L,20L);cols<-c(blue,ink)
methods<-c('UPR_priority','raw_UPR','generic_magnitude','DepMap','expression');labels<-c('UPR + agreement','Raw UPR','Three-program norm','Essentiality','Expression','Matched modules','Uniform ordering')
refs<-do.call(rbind,lapply(ks,function(k)do.call(rbind,lapply(c('Precision','NDCG'),function(e){z<-subset(null,K==k)[[e]];u<-subset(unif,endpoint==paste0(e,k));rbind(data.frame(reference='Matched random modules',K=k,endpoint=e,estimate=median(z),low=quantile(z,.025),high=quantile(z,.975)),data.frame(reference='Uniform random ordering',K=k,endpoint=e,estimate=u$expected,low=u$reference_low,high=u$reference_high))}))))
write.table(refs,file.path(p,'ranking_figure_random_reference_source.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
panel<-function(letter,title){mtext(letter,side=3,line=2.05,adj=0,font=2,cex=8/7);mtext(title,side=3,line=.5,adj=0,font=1,cex=1)}
plot_rank<-function(metric,letter,title,xlim){par(mar=c(4,8.5,3.2,.6));plot(NA,xlim=xlim,ylim=c(.5,7.5),axes=FALSE,xlab=if(metric=='Precision')'Fraction with signed RPE1 effect > 0'else'Linear-gain NDCG',ylab='',xaxs='i',yaxs='i');axis(1,tcl=-.2);axis(2,at=7:1,labels=labels,las=1,tick=FALSE);box(bty='l',lwd=.6)
 for(j in 1:2){k<-ks[j];off<-if(j==1).11 else -.11;for(i in seq_along(methods)){d<-subset(m,method==methods[i]&K==k);points(d[[metric]],8-i+off,pch=if(j==1)16 else 1,col=cols[j],cex=.8)};for(i in 1:2){ref<-c('Matched random modules','Uniform random ordering')[i];d<-subset(refs,reference==ref&K==k&endpoint==metric);yy<-3-i+off;segments(d$low,yy,d$high,yy,col=grey,lwd=.9);points(d$estimate,yy,pch=if(j==1)16 else 1,col=cols[j],cex=.65)}}
 if(metric=='Precision')abline(v=unif$cohort_positive_prevalence[1],lty=3,col=grey)
 legend('bottomright',legend=c('Top 10','Top 20'),pch=c(16,1),col=cols,bty='n',cex=1,inset=.01,x.intersp=.7,y.intersp=.9)
 panel(letter,title)
}
draw<-function(){layout(matrix(1:4,2,2,byrow=TRUE),heights=c(1,1.05),widths=c(1,1.08));par(family='Helvetica',ps=7,cex=1,lwd=.65,mgp=c(2.1,.55,0),tcl=-.2,xaxs='i',yaxs='i')
 par(mar=c(4,4.4,3.2,.7));ylim<-range(c(genes$RPE1_d,q$mean_low,q$mean_high));ylim<-ylim+c(-.08,.08);plot(NA,xlim=c(.6,5.4),ylim=ylim,xlab='Source signed-UPR quintile',ylab='Signed RPE1 UPR effect (control SD)',axes=FALSE);axis(1,at=1:5,labels=paste0('Q',1:5));axis(2,las=1);box(bty='l');abline(h=0,col=light,lwd=.7)
 set.seed(2026110619);points(genes$quintile+runif(nrow(genes),-.18,.18),genes$RPE1_d,pch=16,col=adjustcolor(grey,alpha.f=.55),cex=.33);lines(q$quintile,q$RPE1_mean,col=blue,lwd=1);segments(q$quintile,q$mean_low,q$quintile,q$mean_high,col=blue,lwd=1);points(q$quintile,q$RPE1_mean,pch=16,col=blue,cex=.75);segments(q$quintile-.10,q$RPE1_median,q$quintile+.10,q$RPE1_median,col=ink,lwd=1)
 legend('bottomleft',legend=c('Mean (95% gene interval)','Median'),pch=c(16,NA),lty=c(NA,1),col=c(blue,ink),bty='n',cex=1,y.intersp=.95,seg.len=.8,x.intersp=.6)
 panel('a','Overall gradient; upper means are not ordered')
 par(mar=c(4,4.3,3.2,.7));plot(NA,xlim=c(.6,5.4),ylim=c(0,.7),axes=FALSE,xlab='Source signed-UPR quintile',ylab='Fraction with signed RPE1 effect > 0');axis(1,at=1:5,labels=paste0('Q',1:5));axis(2,at=seq(0,.6,.2),las=1);box(bty='l');abline(h=mean(genes$RPE1_d>0),col=grey,lty=3);segments(q$quintile,q$positive_low,q$quintile,q$positive_high,col=blue,lwd=1);points(q$quintile,q$positive_fraction,pch=16,col=blue,cex=.75);text(1:5,.665,labels=paste0(q$positive,'/',q$genes),cex=1);text(5.32,mean(genes$RPE1_d>0)+.025,'Cohort',adj=1,col=ink,cex=1);panel('b','Positive signs become more frequent')
 plot_rank('Precision','c','Fixed source rankings: positive signs',c(0,1))
 plot_rank('NDCG','d','No demonstrated gain from weighting',c(0,.52))
}
base<-file.path(p,'Fig_UPR_quintiles_ranking_robustness')
if(Sys.info()[['sysname']]=='Darwin')quartz(type='pdf',file=paste0(base,'.pdf'),width=183/25.4,height=162/25.4,family='Helvetica',pointsize=7)else cairo_pdf(paste0(base,'.pdf'),width=183/25.4,height=162/25.4,family='Helvetica',pointsize=7);draw();dev.off()
svglite::svglite(paste0(base,'.svg'),width=183/25.4,height=162/25.4);draw();dev.off()
ragg::agg_png(paste0(base,'_actual_size.png'),width=183,height=162,units='mm',res=150,pointsize=7);draw();dev.off()
ragg::agg_png(paste0(base,'_preview.png'),width=183,height=162,units='mm',res=300,pointsize=7);draw();dev.off()
writeLines(c('Source-UPR quintile gradients and fixed ranking utility in previously evaluated RPE1 data.',
'a, The 438 metadata-eligible genes grouped into balanced quintiles using signed source K562 UPR effect, with exact ties broken by gene symbol; group sizes are 88, 88, 88, 87 and 87. Grey points are genes; blue points and lines show observed RPE1 means, bars are 95% whole-gene bootstrap intervals, and short black segments denote medians. Means increase from Q1 through Q4 but decrease in Q5; a positive overall trend does not establish strict monotonicity. Quintile membership remains fixed in every resampling draw.',
'b, Positive RPE1 signs (d > 0) and 95% whole-gene intervals in the same 438-gene population; labels give positive/total gene counts. The dotted line denotes cohort positive prevalence. This fixed sign endpoint does not impose a minimum biologically meaningful effect or measure functional activation.',
'c,d, Fixed Top 10 (filled blue) and Top 20 (open black) source rankings on the common 370-gene comparator population. Precision is the proportion with signed RPE1 effect > 0. NDCG uses linear relevance max(d, 0) and standard log2 rank discounts; validation-ideal ordering is only a descriptive normalization. Named-method points are observed values for the fixed lists. Paired whole-gene and shared-GEM intervals, together with the joint Holm7 tests, are provided in the accompanying tables. Bars on computational reference rows instead show central 95% distributions across 100 fixed expression/detection-matched random-module lists or 10,000 uniform random orderings; they are not biological confidence intervals. The agreement-weighted and raw-UPR Top 10 lists contain the same genes, but their internal source order differs and therefore gives different NDCG.',
'All analyses are retrospective robustness extensions: RPE1 outcomes had already been evaluated. RPE1 is a held-out cellular context in the same published study as K562. The locked joint Holm7 family covers three all-gene quintile tests and four priority-minus-raw-UPR utility differences; none of the latter differences demonstrates a weighting advantage after correction. Source rankings, K, sign threshold, gene universe and null memberships were unchanged. Whole-gene intervals condition on fixed source groups; technical GEM, equal-cell and exact-denominator sensitivities are reported separately. Figure source tables: source_quintile_membership.tsv, quintile_group_summaries.tsv, fixed_ranking_metrics.tsv, ranking_figure_random_reference_source.tsv and joint_Holm7_tests.tsv.'),paste0(base,'_legend.txt'))
writeLines(c('Vector PDF/SVG generated directly in R,183mm wide by162mm high. Helvetica body7pt/panel labels8pt. Native R150dpi actual-size and300dpi previews produced. Scientific scope: retrospective fixed-list transcriptional ranking; no new independent validation, causal pathway test or functional efficacy claim. Final visual inspection remains required before delivery.'),paste0(base,'_quality_scope.txt'))
